stmt.execute("""
    CREATE TABLE users (
        id INT PRIMARY KEY,
        name VARCHAR(100) NOT NULL,
        email VARCHAR(100) NOT NULL
    )
    """);

stmt.execute("""
    CREATE TABLE orders (
        id INT PRIMARY KEY,
        user_id INT NOT NULL,
        order_date DATE NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )
    """);

// "orders" odwoluje sie do "users" (kto zlozyl zamowienie).
// "order_items" odwoluje sie i do "orders", i do "products" -
// typowy wzorzec relacji wiele-do-wielu przez tabele posrednia
// (dokladniej w Lesson03_TableDesign).

// Probujemy wstawic zamowienie z user_id, ktory NIE ISTNIEJE
// w tabeli users. Baza danych to ODRZUCI - klucz obcy pilnuje
// integralnosci danych.

try {
    stmt.execute("INSERT INTO orders VALUES (99, 999, '2026-03-01')"); // user_id=999 nie istnieje!
    System.out.println("To sie nie powinno wykonac!");
} catch (SQLException e) {
    System.out.println("Odrzucono przez baze (integralnosc referencyjna): " + e.getMessage());
}
